options.script:
const frame = data.series[0];
const column = (name) => {
  const field = frame ? frame.fields.find((f) => f.name === name) : null;
  return field ? Array.from(field.values.toArray ? field.values.toArray() : field.values) : [];
};
const fpr = column('fpr'), tpr = column('tpr'), auroc = column('au_roc')[0];
const axis = { type: 'linear', autorange: false, range: [0, 1], dtick: 0.25, constrain: 'domain', zeroline: false };
return {
  data: [
    { x: [0, 1], y: [0, 1], mode: 'lines', line: { dash: 'dash', width: 1, color: 'gray' }, name: 'chance', hoverinfo: 'skip' },
    { x: fpr, y: tpr, mode: 'lines', line: { width: 2 }, name: 'ROC',
      hovertemplate: 'FPR %{x:.3f}<br>TPR %{y:.3f}<extra></extra>' }
  ],
  layout: {
    title: { text: auroc === undefined ? '' : 'I-AUROC ' + auroc.toFixed(3), font: { size: 13 } },
    showlegend: false,
    margin: { l: 45, r: 10, t: 30, b: 40 },
    xaxis: Object.assign({ title: { text: 'False positive rate' } }, axis),
    yaxis: Object.assign({ title: { text: 'True positive rate' }, scaleanchor: 'x', scaleratio: 1 }, axis)
  },
  config: { displayModeBar: false }
};
